import gurobipy as gp
from gurobipy import GRB
vehicle_types = []
vehicle_ids = []
capacity_by_type = {}
benefit_by_type = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        vtype = rec['values']['VehicleType']
        vid = int(rec['values']['VehicleID'])
        cap = int(rec['values']['Capacity'])
        vehicle_types.append(vtype)
        vehicle_ids.append(vid)
        capacity_by_type[vtype] = cap
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('products.csv'):
        vtype = rec['values']['ProductName']
        benefit_by_type[vtype] = int(rec['values']['Value'])
vehicle_info = sorted([(vid, vtype) for (vid, vtype) in zip(vehicle_ids, vehicle_types)], key=lambda x: x[0])
vehicle_ids = [vid for (vid, vtype) in vehicle_info]
vehicle_types = [vtype for (vid, vtype) in vehicle_info]
for vtype in vehicle_types:
    if vtype not in benefit_by_type:
        raise ValueError(f'Missing benefit coefficient for vehicle type {vtype}')
    if vtype not in capacity_by_type:
        raise ValueError(f'Missing capacity for vehicle type {vtype}')
total_capacity = sum((capacity_by_type[vtype] for vtype in vehicle_types))
m = gp.Model('NewCarSalesInNorway')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(vehicle_types, lb=0, ub={vtype: capacity_by_type[vtype] for vtype in vehicle_types}, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit_by_type[vtype] * x_vars[vtype] for vtype in vehicle_types)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((x_vars[vtype] for vtype in vehicle_types)) <= total_capacity, name='total_capacity')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for vtype in vehicle_types:
        print(f'x[{vtype}]: {x_vars[vtype].X}')
else:
    print(f'Solver status: {m.Status}')
